def shift_down(grid, bg=None):
    """Every row moved down one; the top row becomes a row of the background color (most common cell)."""
    from collections import Counter
    if bg is None:
        bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    return [[bg]*len(grid[0])] + grid[:-1]
